	tech_etl.util_text_to_null_validation(exp02."BSTKD_LOT") AS "BSTKD_LOT_exp02",								-- Контракт в лоте/Квотный контракт
	tech_etl.util_text_to_date_validation(exp03."TCON_TO_BUYER_DATE") AS "TCON_TO_BUYER_DATE_exp03",			-- Дата перехода из консигнации клиенту
	tech_etl.util_text_to_date_validation(exp03."LDDAT_FREL") AS "LDDAT_FREL_exp03",							-- Дата Финальный релиз
	tech_etl.util_text_to_null_validation(exp04."FWH_EXIST") AS "FWH_EXIST_exp04",								-- Наличие Иностранный склад
	tech_etl.util_text_to_date_validation(exp03."DATAUNLOAD") AS "DATAUNLOAD_exp03",							-- ТН/CMR: Дата выгрузки авто
	tech_etl.util_text_to_null_validation(exp04."RIVER_EU") AS "RIVER_EU_exp04",								-- Наличие Иностранный склад 2
	tech_etl.util_text_to_null_validation(exp03."LOCID_FP2") AS "LOCID_FP2_exp03",								-- Иностранный порт 2 (код локации)
	tech_etl.util_text_to_date_validation(exp03."UL_ATA_DATE") AS "UL_ATA_DATE_exp03",							-- Дата прибытия УЛ
	tech_etl.util_text_to_date_validation(exp02."DATE_PERETAR") AS "DATE_PERETAR_exp02",						-- Дата перетарки
	tech_etl.util_text_to_null_validation(exp03."SVH_TXT") AS "SVH_TXT_exp03",									-- СВХ
	exp04."BRUTTO_02" AS "BRUTTO_02_exp04",																		-- Вес брутто (с учетом склада)
	tech_etl.util_text_to_null_validation(exp04."STATUS_ZHD") AS "STATUS_ZHD_exp04",							-- Статус движения по ЖД
	tech_etl.util_text_to_null_validation(exp04."STATUS_SCB") AS "STATUS_SCB_exp04",							-- Статус в Supply chain (Business)
	tech_etl.util_text_to_null_validation(exp03."KNOTE_PLAN2") AS "KNOTE_PLAN2_exp03",							-- Плановый порт выгрузки 2 (код)
