	exp04."COMMITM" AS "COMMITM_exp04",																			-- Объем обязательств
	exp04."COMMITM_TOTAL" AS "COMMITM_TOTAL_exp04",																-- Объем обязательств итого
	tech_etl.util_text_to_null_validation(exp02."VTEXT_L") AS "VTEXT_L_exp02",									-- Номер лота
	tech_etl.util_text_to_null_validation(exp04."HMG") AS "HMG_exp04",											-- HMG
	tech_etl.util_text_to_null_validation(exp02."PORT_Y_LAND1") AS "PORT_Y_LAND1_exp02",						-- Страна порта выгрузки
	tech_etl.util_text_to_date_validation(exp04."STORAGE_CONFIRMATION") AS "STORAGE_CONFIRMATION_exp04",		-- Дата Storage confirmation
