	tech_etl.util_text_to_date_validation(exp03."LDDAT_REL") AS "LDDAT_REL_exp03",								-- Дата релиз
	tech_etl.util_text_to_null_validation(exp03."VTEXT_NOT") AS "VTEXT_NOT_exp03",								-- Номер нотиса
	tech_etl.util_text_to_date_validation(exp03."LDDAT_NOT") AS "LDDAT_NOT_exp03",								-- Дата нотиса
	tech_etl.util_text_to_null_validation(exp03."VTEXT_FREL") AS "VTEXT_FREL_exp03",							-- Номер Финальный релиз
	tech_etl.util_text_to_date_validation(exp04."BUDAT_FIN") AS "BUDAT_FIN_exp04",								-- Дата оплаты Final Invoice
	tech_etl.util_text_to_null_validation(exp03."CONTAINER_OUT") AS "CONTAINER_OUT_exp03",						-- Номер ТС в ин. порту
	tech_etl.util_text_to_null_validation(exp03."SDABW_PORT") AS "SDABW_PORT_exp03",							-- Тип ТС в ин. порту
	tech_etl.util_text_to_null_validation(exp01."MARKET_TXT") AS "MARKET_TXT_exp01",							-- Рынок в отгрузке
	tech_etl.util_text_to_null_validation(exp03."TCON") AS "TCON_exp03",										-- Признак консигнации
	tech_etl.util_text_to_date_validation(exp03."TCON_TO_BUYER_DATE") AS "TCON_TO_BUYER_DATE_exp03",			-- Дата перехода из консигнации клиенту
	tech_etl.util_text_to_date_validation(exp03."DATAUNLOAD") AS "DATAUNLOAD_exp03",							-- ТН/CMR: Дата выгрузки авто
	tech_etl.util_text_to_null_validation(exp04."ID_WAY") AS "ID_WAY_exp04",									-- Сценарий маршрута
	tech_etl.util_text_to_null_validation(exp04."LANDX") AS "LANDX_exp04",										-- Страна поставки по контракту
	tech_etl.util_text_to_null_validation(exp04."REALIZATION_STATUS") AS "REALIZATION_STATUS_exp04",			-- Статус Реализации
	tech_etl.util_text_to_null_validation(exp01."SVH_02_EXIST") AS "SVH_02_EXIST_exp01",						-- Есть запись с кодом СВХ 02
	tech_etl.util_text_to_null_validation(exp04."DELIV_REGION") AS "DELIV_REGION_exp04",						-- Регион поставки
	left(tech_etl.util_text_to_null_validation(exp01."DATEOT"), 6) AS "DATEOT_exp01_month_year",				-- Месяц и год отгрузки
	tech_etl.util_text_to_null_validation(exp03."VOYAGE") AS "VOYAGE_exp03",									-- Номер рейса
	tech_etl.util_text_to_null_validation(exp03."SVH_CODE") AS "SVH_CODE_exp03",								-- Тип СВХ(код)
	tech_etl.util_text_to_null_validation(exp01."CUSTOMID") AS "CUSTOMID_exp01",								-- Заказчик
	tech_etl.util_text_to_null_validation(exp01."MMCL_CODE") AS "MMCL_CODE_exp01",								-- Код марки клиента
	tech_etl.util_text_to_null_validation(exp04."STATUS_SC") AS "STATUS_SC_exp04",								-- Статус в Supply chain (Portal)
	tech_etl.util_text_to_null_validation(exp03."PLEDGE_CLIENT") AS "PLEDGE_CLIENT_exp03",						-- Pledge Bank (code)
	tech_etl.util_text_to_date_validation(exp04."REALIZATION_DATE_PF") AS "REALIZATION_DATE_PF_exp04",			-- Дата реализации План/Факт
	tech_etl.util_text_to_null_validation(exp01."POTREBIT") AS "POTREB_exp01",									-- Потребитель
	tech_etl.util_text_to_null_validation(exp02."PORT_Y") AS "PORT_Y_exp02",									-- Порт выгрузки (код)
	tech_etl.util_text_to_date_validation(exp03."LDDAT_REA") AS "LDDAT_REA_exp03",								-- Дата Реализации
	tech_etl.util_text_to_null_validation(exp01."SYSTEMID") AS "SYSTEMID_exp01",								-- Внутренний уникальный идентификатор записи
	tech_etl.util_text_to_null_validation(exp01."MATKL") AS "MATKL_exp01",										-- Группа материалов
	tech_etl.util_text_to_null_validation(exp01."PIMARY") AS "PIMARY_exp01",									-- Материал
	tech_etl.util_text_to_date_validation(exp02."DATAPRZD_RF") AS "DATAPRZD_RF_exp02",							-- Плановая дата принятия в порту
