	tech_etl.util_text_to_date_validation(exp03."PLSTDATFR2") AS "PLSTDATFR2_exp03",							-- Плановая дата отгрузки со склада ин. порта 2
	exp04."DAYS1"::integer AS "DAYS1_exp04",																	-- Норма приемки контейнера в портy
	exp04."FWH_DAYS1"::integer AS "FWH_DAYS1_exp04",															-- Норма приемки терминал/склад ин. порта
	exp04."FWH2_DAYS1"::integer AS "FWH2_DAYS1_exp04",															-- Норма приемки терминал/склад ин. порта 2
	tech_etl.util_text_to_date_validation(exp02."EXPECTED_BL_EXP") AS "EXPECTED_BL_EXP_exp02",					-- Дата коносамента план
	tech_etl.util_text_to_date_validation(exp04."LDDAT_KOP_P") AS "LDDAT_KOP_P_exp04",							-- Дата коносамента в ин.порту план
	tech_etl.util_text_to_date_validation(exp02."DATAPRZD_P") AS "DATAPRZD_P_exp02",							-- Плановая дата прибытия по ЖД (с фактом)
	tech_etl.util_text_to_null_validation(exp01."ORDER_") AS "ORDER_exp01",										-- Заказ ЦК в отгрузке
	tech_etl.util_text_to_null_validation(exp01."PLATF") AS "PLATF_exp01",										-- Платформа
	tech_etl.util_text_to_null_validation(exp02."MAKTX") AS "MAKTX_exp02",										-- Наименование материала
	tech_etl.util_text_to_null_validation(exp01."ROUTE_SHIP") AS "ROUTE_SHIP_exp01",							-- Маршрут в отгрузке
	tech_etl.util_text_to_null_validation(exp01."SDABW_SHIP") AS "SDABW_SHIP_exp01",							-- Тип вагона, указанный в графике отгрузке на заводе-производ.
	tech_etl.util_text_to_date_validation(exp02."UNLOADDATE_Y") AS "UNLOADDATE_Y_exp02",						-- Дата выгрузки в порту
	tech_etl.util_text_to_null_validation(exp02."VAGON_P") AS "VAGON_P_exp02",									-- Контейнер
	tech_etl.util_text_to_null_validation(exp01."PLANT") AS "PLANT_exp01",										-- Завод (код)
	tech_etl.util_text_to_null_validation(exp01."NSERT") AS "NSERT_exp01",										-- Номер сертификата
	tech_etl.util_text_to_null_validation(exp02."KUNAG_L") AS "KUNAG_L_exp02",									-- Покупатель в лоте
	tech_etl.util_text_to_null_validation(exp04."MIRR_STATUS") AS "MIRR_STATUS_exp04",							-- Статус зеркалирования
	tech_etl.util_text_to_null_validation(exp02."BUYER_TXT") AS "BUYER_TXT_exp02",								-- Плановый покупатель 
	tech_etl.util_text_to_null_validation(exp01."LGORT") AS "LGORT_exp01",										-- Принимающий склад
	CASE 
        WHEN COALESCE(exp01."VBELN_P", exp02."VBELN_P", exp03."VBELN_P", exp04."VBELN_P") IS NOT NULL
            AND COALESCE(exp01."VBELN_P", exp02."VBELN_P", exp03."VBELN_P", exp04."VBELN_P") = exp01."VBELN_P"
            AND COALESCE(exp01."VBELN_P", exp02."VBELN_P", exp03."VBELN_P", exp04."VBELN_P") = exp02."VBELN_P"
            AND COALESCE(exp01."VBELN_P", exp02."VBELN_P", exp03."VBELN_P", exp04."VBELN_P") = exp03."VBELN_P"
            AND COALESCE(exp01."VBELN_P", exp02."VBELN_P", exp03."VBELN_P", exp04."VBELN_P") = exp04."VBELN_P"
            AND COALESCE(exp01."CHARG", exp02."CHARG", exp03."CHARG", exp04."CHARG") = exp01."CHARG"
            AND COALESCE(exp01."CHARG", exp02."CHARG", exp03."CHARG", exp04."CHARG") = exp02."CHARG"
            AND COALESCE(exp01."CHARG", exp02."CHARG", exp03."CHARG", exp04."CHARG") = exp03."CHARG"
            AND COALESCE(exp01."CHARG", exp02."CHARG", exp03."CHARG", exp04."CHARG") = exp04."CHARG"
        THEN false
        ELSE true
    END AS is_delivery_not_exist_in_all_stg_tables
FROM 
	stg."ZMK_TRACK_EXP01" AS exp01
full JOIN 
	stg."ZMK_TRACK_EXP02" AS exp02 
	ON exp01."VBELN_P" = exp02."VBELN_P" 
		AND exp01."CHARG" = exp02."CHARG" 
		AND exp01."GUID_KEY" = exp02."GUID_KEY"
full JOIN 
	stg."ZMK_TRACK_EXP03" AS exp03 
	ON exp01."VBELN_P" = exp03."VBELN_P"  
		AND exp01."CHARG" = exp03."CHARG" 
		AND exp01."GUID_KEY" = exp03."GUID_KEY"
full JOIN 
	stg."ZMK_TRACK_EXP04" AS exp04 
	ON exp01."VBELN_P" = exp04."VBELN_P" 
		AND exp01."CHARG" = exp04."CHARG" 
		AND exp01."GUID_KEY" = exp04."GUID_KEY"
WHERE 
	exp01."CHARG" NOT LIKE ' %'
	AND exp01."CHARG" IS NOT NULL
	AND exp01."DATEOT" NOT LIKE ' %'
	AND exp01."DATEOT" >= '20220101'
;
